  public void Initialize(GameRuntime runtime,string selected,int i){game=runtime;actionSurface=StartAction.GetComponent<Image>();viewport=game.Content.GetComponentInParent<ScrollRect>().viewport;kind=selected;index=i;id=kind=="training"?PrestigeAutomation.Tracks[i]:Balance.Research[i].Id;if(kind=="research"){Card.Button.onClick.RemoveAllListeners();Card.Button.onClick.AddListener(()=>game.ShowDetails(kind,index));StartAction.onClick.AddListener(()=>game.Act(v=>Game.Research(v,id),"research-project"));CompactResearch();}else StartAction.onClick.AddListener(()=>Card.Button.onClick.Invoke());Details.name="Details-"+kind+"-"+id;Details.onClick.AddListener(()=>game.ShowDetails(kind,index));var shell=game.GetComponent<MobileShell>();CreditIcon.sprite=game.Credits.transform.parent.Find("ResourceIcon")?.GetComponent<Image>()?.sprite??shell.ResourceIcons[0];DataIcon.sprite=game.Data.transform.parent.Find("ResourceIcon")?.GetComponent<Image>()?.sprite??shell.ResourceIcons[1];foreach(var resource in new[]{CreditIcon,DataIcon}){var group=resource.transform.parent.GetComponent<HorizontalLayoutGroup>();group.childForceExpandWidth=group.childForceExpandHeight=false;group.childAlignment=TextAnchor.MiddleLeft;var glyph=resource.GetComponent<LayoutElement>();glyph.minWidth=glyph.preferredWidth=20;glyph.minHeight=glyph.preferredHeight=20;glyph.flexibleWidth=glyph.flexibleHeight=0;var amount=resource.transform.parent.GetComponentInChildren<Text>().GetComponent<LayoutElement>();amount.flexibleWidth=1;}int area=kind=="training"?(i==0?2:i==1?1:3):Workshop.ResearchArea(id);Card.Icon.sprite=area==0?game.ResearchTab.transform.Find("NavigationIcon").GetComponent<Image>().sprite:area==1?game.HardwareSprites[1]:area==2?game.ModelPrefab.ModelArt:area==3?game.WorkshopPrefab.ComponentSprites[0]:game.ResearchTab.transform.Find("NavigationIcon").GetComponent<Image>().sprite;RefreshView();}
