    else{quotedBlock=Game.ResearchBlock(s,index);if(quotedBlock=="Zu wenig Daten")quotedBlock=null;queueAllowed=quotedBlock=="Labor belegt"&&PrestigeAutomation.CanQueueResearch(s,id);string text=ResearchCopy.Describe(s,id);Effect.text=text.Length>60?text.Substring(0,57)+"…":text;if(!Balance.Research[index].Project){var after=s.Copy();after.Research[index]++;Func<GameState,ScientificNumber> metric=id=="dataGeneration"||id=="syntheticData"||id=="dataFlywheel"?Game.DataRate:id=="computeOptimization"||id=="hardwareIntegration"||id=="parallelArchitecture"||id=="hardwareCoDesign"||id=="distributedInference"?Game.Compute:(Func<GameState,ScientificNumber>)null;if(metric!=null)Effect.text=N(metric(s))+" → "+N(metric(after))+((id=="dataGeneration"||id=="syntheticData"||id=="dataFlywheel")?(de?" Daten/s":" Data/s"):" Compute")+"\n"+(text.Length>36?text.Substring(0,33)+"…":text);}}
   }
   Credits.color=s.Credits.CompareTo(cost)>=0?GameTheme.Enough:GameTheme.Missing;Data.color=s.Data.CompareTo(dataCost)>=0?GameTheme.Enough:GameTheme.Missing;Job job=training?(s.Training?.id==id?s.Training:null):PrestigeAutomation.ResearchJobs(s).FirstOrDefault(j=>j.id==id);bool queued=training?s.Prestige.trainingQueue.Any(q=>q.track==id):s.Prestige.researchQueue.Contains(id);bool can;
   if(training){bool queue=s.Training!=null&&PrestigeRules.Has(s,"T03")&&s.Prestige.trainingQueue.Length<2;can=allowed&&(s.Training==null?s.Credits.CompareTo(cost)>=0&&s.Data.CompareTo(dataCost)>=0:queue);ActionLabel.text=s.Training!=null&&queue?(de?"Einreihen":"Queue"):(de?"Trainieren":"Train");}
   else{string block=quotedBlock;if(block==null&&s.Data.CompareTo(dataCost)<0)block="Zu wenig Daten";can=block==null||block=="Labor belegt"&&queueAllowed;Requirement.text=job!=null?"":queued?(de?"In Warteschlange":"Queued"):Human(block);ActionLabel.text=block=="Labor belegt"?(de?"Einreihen":"Queue"):(de?"Forschen":"Research");}
   if(job!=null){if(training)Card.Title.text=Name(id)+" · Lv. "+(current+1);double speed=training?Game.WorkSpeed(s):Game.ResearchSpeed(s,job);if(job.intro)speed=1;Duration.text=LearningPresentation.Remaining(training?(job.required-job.done)/speed:Game.ResearchRemainingSeconds(s,job),language,true);Requirement.text=de?"Training läuft":"Training in progress";if(!training)Requirement.text=de?"Labor arbeitet":"Research in progress";ActionLabel.text=de?"Läuft":"Running";}CreditIcon.transform.parent.gameObject.SetActive(job==null&&training);DataIcon.transform.parent.gameObject.SetActive(job==null&&(!training||!dataCost.IsZero));Requirement.gameObject.SetActive(Requirement.text.Length>0);bool queueAction=training&&job!=null&&can;if(training)StartAction.transform.parent.gameObject.SetActive(job==null||queueAction);else{StartAction.gameObject.SetActive(job==null);Requirement.text=queued?(de?"Wartend":"Queued"):job!=null?(de?"Läuft":"Running"):can?"":(de?"Voraussetzung fehlt · Details":"Requirement missing · Details");Requirement.gameObject.SetActive(Requirement.text.Length>0);}if(queueAction)ActionLabel.text=de?"Einreihen":"Queue";Progress.gameObject.SetActive(job!=null);Progress.fillAmount=job==null?0:(float)Math.Min(1,job.done/job.required);StartAction.interactable=game.Writable&&can;Card.Button.interactable=!training||game.Writable&&can;actionSurface.sprite=StartAction.interactable?GameTheme.GoldButton:GameTheme.Steel;ActionLabel.color=StartAction.interactable?GameTheme.Background:GameTheme.Muted;}
